{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "config": {
    "kibana": {
      "hideWarnings": true
    },
    "view": {
      "stroke": null
    }
  },
  "data": {
    "format": {
      "property": "aggregations.lv.buckets"
    },
    "url": {
      "body": {
        "aggs": {
          "lv": {
            "filters": {
              "filters": [
                {
                  "match_all": {}
                },
                {
                  "range": {
                    "rule.level": {
                      "gte": 7,
                      "lte": 11
                    }
                  }
                },
                {
                  "range": {
                    "rule.level": {
                      "gte": 12
                    }
                  }
                }
              ]
            }
          }
        },
        "query": {
          "bool": {
            "filter": [
              "%dashboard_context-filter_clause%"
            ],
            "must": [
              "%dashboard_context-must_clause%",
              {
                "range": {
                  "timestamp": {
                    "%timefilter%": true
                  }
                }
              },
              {
                "query_string": {
                  "analyze_wildcard": true,
                  "query": "rule.id:[133500 TO 133599] AND rule.id:/[0-9]{6}/"
                }
              }
            ],
            "must_not": [
              "%dashboard_context-must_not_clause%"
            ]
          }
        },
        "size": 0
      },
      "index": "wazuh-alerts-*"
    }
  },
  "encoding": {
    "x": {
      "axis": null,
      "field": "ord",
      "type": "ordinal"
    }
  },
  "layer": [
    {
      "encoding": {
        "color": {
          "field": "colour",
          "scale": null,
          "type": "nominal"
        },
        "text": {
          "field": "num"
        }
      },
      "mark": {
        "baseline": "bottom",
        "dy": -4,
        "fontSize": 34,
        "fontWeight": "bold",
        "type": "text"
      }
    },
    {
      "encoding": {
        "text": {
          "field": "label"
        }
      },
      "mark": {
        "baseline": "top",
        "color": "#3d444d",
        "dy": 6,
        "fontSize": 13,
        "type": "text"
      }
    }
  ],
  "transform": [
    {
      "window": [
        {
          "as": "ord",
          "op": "row_number"
        }
      ]
    },
    {
      "as": "num",
      "calculate": "format(datum.doc_count, ',')"
    },
    {
      "as": "label",
      "calculate": "datum.ord == 1 ? '全部告警' : (datum.ord == 2 ? '等級 7–11' : '等級 12 以上')"
    },
    {
      "as": "colour",
      "calculate": "datum.ord == 1 ? '#1f5bb0' : (datum.doc_count == 0 ? '#2e7d32' : (datum.ord == 2 ? '#b26a00' : '#c62828'))"
    }
  ]
}"},"title":"jt-modsecurity · 告警數","type":"vega"}

